const id=()=>crypto.randomUUID(),zone=()=>state.settings?.zone||Intl.DateTimeFormat().resolvedOptions().timeZone||'Asia/Kolkata',today=()=>dayKey(Date.now(),zone()),fmt=n=>Math.round(n),button=(label,action,extra='',cls='')=>`<button type="button" class="${cls}" data-action="${action}" ${extra}>${label}</button>`,link=(url,label)=>`<a class="button" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`,empty=t=>`<div class="empty">${t}</div>`;
