async function mutate(fn){$('#save-status').textContent='Saving…';try{await store.change(fn);state=store.get();$('#save-status').textContent='Saved';return true;}catch(e){$('#save-status').textContent='Not saved';$('#notice').textContent=e.message;toast(e.message);return false;}}
