function render(){route=(location.hash.slice(1)||'today').split('/')[0];const names={today:['◈','Today'],roadmap:['▦','Roadmap'],questions:['≡','Questions'],review:['↺','Review'],knowledge:['⌘','Java lab'],notebook:['▤','Notebook'],mocks:['◷','Mocks'],progress:['▥','Progress'],settings:['⚙','Settings']};if(!names[route])route='today';$('#nav').innerHTML=Object.entries(names).map(([k,[icon,title]])=>`<a href="#${k}" class="${k===route?'active':''}" ${k===route?'aria-current="page"':''}><span class="navicon" aria-hidden="true">${icon}</span>${title}</a>`).join('');$('#breadcrumb').textContent='Workspace / '+names[route][1];document.title=names[route][1]+' · DSA Forge';
 if(store.fault()){$('#notice').textContent='Stored data could not be loaded. It has not been overwritten. Open Settings to recover.';$('#main').innerHTML=settingsView();return;}
 if(!state.settings&&route!=='settings'){$('#main').innerHTML=head('YOUR NEXT 90 DAYS','Build understanding. Keep it.','A structured Java practice workspace, ready when you are.')+`<div class="panel"><h2>Start with a plan that fits your week</h2><p>150 core questions, 48 patterns, spaced review, and your own learning notes.</p>${button('Set up my 90 days','onboard','','primary')}<p class="muted small" style="margin-top:16px">No account required. Your progress stays in this browser. Export backups to move between devices.</p></div>`;return;}
 const views={today:todayView,roadmap:roadmapView,questions:questionsView,review:reviewView,knowledge:knowledgeView,notebook:notebookView,mocks:mocksView,progress:progressView,settings:settingsView};$('#main').innerHTML=views[route]();tick();}
