function questionsView(){const list=filteredQuestions();return head('THE PRACTICE CATALOGUE','Questions','150 core · 30 extensions · one canonical record per problem')+`<div class="filters"><input id="q-search" aria-label="Search questions by title or ID" placeholder="Search title or LeetCode ID…" value="${esc(filter.search)}"><select data-filter="tier" aria-label="Track">${options(['Core','Extension'],filter.tier,'All tracks')}</select><select data-filter="difficulty" aria-label="Difficulty">${options(['Easy','Medium','Hard'],filter.difficulty,'All difficulties')}</select><select data-filter="status" aria-label="Status">${options(['Not started','Attempting','Learned','Solved independently','Retained','Bookmarked','Review due'],filter.status,'All statuses')}</select></div><div class="filters"><select data-filter="pattern" aria-label="Pattern">${options(patterns.map(p=>[p.id,p.title]),filter.pattern,'All 48 patterns')}</select><select data-filter="topic" aria-label="Topic">${options([...new Set(patterns.map(p=>p.topic))],filter.topic,'All topics')}</select><select data-filter="sort" aria-label="Sort questions">${options([['order','Learning order'],['difficulty','Difficulty'],['title','Title']],filter.sort)}</select></div><p class="small">${list.length} results. Estimated time is for a first attempt, not a deadline.</p><div id="question-results">${questionResults(list)}</div>`;}
