function roadmapView(){return head('A DATED, FINITE PLAN','Your 90-day roadmap',`${state.settings.start} — ${addDays(state.settings.start,89)}. Final 13 days protect revision.`,button('Preview catch-up','catchup'))+`<div class="callout">${state.plan.reduce((n,d)=>n+d.total,0)} estimated minutes / ${state.plan.reduce((n,d)=>n+d.capacity,0)} available. ${state.plan.reduce((n,d)=>n+d.overflow,0)} minutes overflow across individual days. ${state.backlog?.length||0} unresolved first attempts remain in backlog. Estimates include at least 25% review/notes time.</div>`+Array.from({length:13},(_,w)=>`<section style="margin-bottom:26px"><div class="section-head"><h2>Week ${w+1}</h2><small>${w===0?'Foundations':w<3?'Hashing, windows & stacks':w<6?'Search, lists, trees & backtracking':w<9?'Graphs & mixed practice':w<11?'Dynamic programming & gaps':'Recall, mocks & repair'}</small></div><div class="week">${state.plan.slice(w*7,w*7+7).map(d=>`<button class="day ${d.date===today()?'today':''} ${d.date<today()?'past':''} ${state.pauses[d.date]?'pause':''}" data-action="day" data-date="${d.date}"><small>${d.date}</small><b>Day ${d.number} ${missionComplete(d)?'✓':''}</b><span>${d.questions.length?d.questions.length+' new attempts':d.mock?'Mock + review':'Review & recall'}</span><small>${d.total} / ${d.capacity} min${d.overflow?' · over budget':''}</small>${state.pauses[d.date]?'<span class="warn">Paused</span>':''}</button>`).join('')}</div></section>`).join('');}
function reviewView(){const due=dueReviews(state,today()),budget=selectedPlan()?.reviewMinutes||30;let used=0;return head('RETRIEVE. REASON. REPEAT.','Review queue',`${due.length} due or overdue · ${budget} min reserved today. A recognition check takes 5 min; a re-solve takes the question’s estimate.`)+`<div class="callout">Write your reasoning before revealing notes. Ratings schedule the next review at roughly 1, 3, 7, 14, and 30 days. Failed recall returns tomorrow.</div>`+(due.length?due.map(([qid,r])=>{const q=qmap[qid];if(!q)return '';used+=5;return `<div class="panel"><div class="section-head"><div><h3>${esc(q.title)}</h3><small>LC ${qid} · due ${r.due} · confidence ${r.confidence}/4 ${used>budget?'· exceeds today’s recognition budget':''}</small></div>${button('Attempt recall','recall',`data-id="${qid}"`,'primary')}</div><p class="small">${esc(pmap[q.pattern].hook)}</p></div>`;}).join(''):empty('No reviews due. Log a problem outcome to schedule your first review.'))+`<h2 style="margin-top:24px">Upcoming</h2>`+Object.entries(state.reviews).filter(([,r])=>r.due>today()).sort((a,b)=>a[1].due.localeCompare(b[1].due)).slice(0,12).map(([qid,r])=>`<p class="small">${r.due} · ${esc(qmap[qid]?.title||'LC '+qid)}</p>`).join('');}
